CREATE TABLE IF NOT EXISTS risk_appetite_statements(id TEXT PRIMARY KEY NOT NULL,code TEXT NOT NULL UNIQUE,category TEXT NOT NULL,statement TEXT NOT NULL,kri_name TEXT NOT NULL,metric_unit TEXT NOT NULL,direction TEXT NOT NULL,appetite_target REAL NOT NULL,warning_threshold REAL NOT NULL,breach_threshold REAL NOT NULL,owner TEXT NOT NULL,reviewer TEXT NOT NULL,frequency_days INTEGER NOT NULL,valid_from TEXT NOT NULL,valid_until TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',next_measurement TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at TEXT NOT NULL,submitted_by TEXT,submitted_at TEXT,decided_by TEXT,decided_at TEXT,decision_note TEXT,retired_by TEXT,retired_at TEXT);
CREATE INDEX IF NOT EXISTS risk_appetite_status_due_idx ON risk_appetite_statements(status,next_measurement,category);
CREATE TABLE IF NOT EXISTS risk_kri_measurements(id TEXT PRIMARY KEY NOT NULL,appetite_id TEXT NOT NULL,period_start TEXT NOT NULL,period_end TEXT NOT NULL,value REAL NOT NULL,band TEXT NOT NULL,source_ref TEXT NOT NULL,evidence_sha256 TEXT NOT NULL,note TEXT NOT NULL,recorded_by TEXT NOT NULL,recorded_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS risk_kri_period_idx ON risk_kri_measurements(appetite_id,period_end);
CREATE INDEX IF NOT EXISTS risk_kri_band_date_idx ON risk_kri_measurements(band,period_end);
CREATE TABLE IF NOT EXISTS risk_kri_breaches(id TEXT PRIMARY KEY NOT NULL,appetite_id TEXT NOT NULL,measurement_id TEXT NOT NULL UNIQUE,severity TEXT NOT NULL,response_owner TEXT,response_plan TEXT,due_date TEXT,status TEXT NOT NULL DEFAULT 'open',evidence_reference TEXT,evidence_sha256 TEXT,detected_by TEXT NOT NULL,detected_at TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at TEXT NOT NULL,submitted_by TEXT,submitted_at TEXT,verified_by TEXT,verified_at TEXT,reopened_by TEXT,reopened_at TEXT);
CREATE INDEX IF NOT EXISTS risk_kri_breaches_status_due_idx ON risk_kri_breaches(status,severity,due_date);
CREATE TABLE IF NOT EXISTS risk_appetite_scenarios(id TEXT PRIMARY KEY NOT NULL,appetite_id TEXT NOT NULL,name TEXT NOT NULL,horizon_days INTEGER NOT NULL,baseline_value REAL NOT NULL,stressed_value REAL NOT NULL,forecast_value REAL NOT NULL,confidence INTEGER NOT NULL,assumptions TEXT NOT NULL,treatment_plan TEXT NOT NULL,owner TEXT NOT NULL,reviewer TEXT NOT NULL,due_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at TEXT NOT NULL,submitted_by TEXT,submitted_at TEXT,verified_by TEXT,verified_at TEXT,verification_note TEXT,evidence_reference TEXT,evidence_sha256 TEXT);
CREATE INDEX IF NOT EXISTS risk_appetite_scenarios_status_due_idx ON risk_appetite_scenarios(status,due_date);
CREATE TABLE IF NOT EXISTS risk_board_snapshots(id TEXT PRIMARY KEY NOT NULL,period TEXT NOT NULL,title TEXT NOT NULL,reviewer TEXT NOT NULL,snapshot_json TEXT NOT NULL,snapshot_sha256 TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'draft',prepared_by TEXT NOT NULL,prepared_at TEXT NOT NULL,approved_by TEXT,approved_at TEXT,approval_note TEXT,evidence_reference TEXT,evidence_sha256 TEXT);
CREATE INDEX IF NOT EXISTS risk_board_snapshots_status_period_idx ON risk_board_snapshots(status,period);
CREATE TABLE IF NOT EXISTS risk_appetite_events(id TEXT PRIMARY KEY NOT NULL,appetite_id TEXT,measurement_id TEXT,breach_id TEXT,scenario_id TEXT,snapshot_id TEXT,action TEXT NOT NULL,detail TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS risk_appetite_events_entity_date_idx ON risk_appetite_events(appetite_id,created_at);
